argv:
$ErrorActionPreference='Stop'
$root='E:\WebAIBridge'; $app=Join-Path $root 'app'
Write-Output '=== GIT ==='
Write-Output ('HEAD='+((& git.exe -C $root rev-parse HEAD).Trim()))
Write-Output ('BRANCH='+((& git.exe -C $root branch --show-current).Trim()))
$chg=@(& git.exe -C $root status --porcelain=v1 --untracked-files=no)
Write-Output ('TRACKED_CHANGES='+$chg.Count)
& git.exe -C $root log -9 --format='%h %s'
Write-Output '=== PRODUCTION ==='
Write-Output ('APP_EXISTS='+(Test-Path $app))
Write-Output ('SERVER_SHA256='+((Get-FileHash -LiteralPath (Join-Path $app 'server.js') -Algorithm SHA256).Hash))
foreach($port in @(17448,17410)) { Write-Output ("LISTEN_$port="+[bool](Get-NetTCPConnection -LocalPort $port -State Listen -ErrorAction SilentlyContinue)) }
foreach($f in @('autonomy-r45-core.js','autonomy-r57-gpt-git.js','autonomy-r57-successor.js','existing-tab-session-r55.js','r65-global-canary-cap.test.js')) { Write-Output ($f+'='+(Test-Path (Join-Path $app $f))) }
Write-Output '=== STATE SAFE FIELDS ==='
$dp=Join-Path $app 'data'
foreach($file in @('state.json','supervisor-watchdog.json','projects-live-control-plane-cutover-r42.json')) {
 $fp=Join-Path $dp $file
 if(-not (Test-Path $fp)){Write-Output ($file+'=MISSING');continue}
 try {
  $j=Get-Content -LiteralPath $fp -Raw | ConvertFrom-Json
  if($file -eq 'state.json'){
    Write-Output ("paused="+$j.settings.paused)
    $as=@($j.agentAssignments)
    Write-Output ('assignments='+$as.Count)
    $as|Group-Object state|ForEach-Object{Write-Output ('assignment_'+$_.Name+'='+$_.Count)}
    Write-Output ('sticky_pin_count='+@($j.stickyExistingTabPins.PSObject.Properties).Count)
  }elseif($file -eq 'supervisor-watchdog.json'){
   Write-Output ("supervisor_enabled="+$j.enabled)
   Write-Output ("supervisor_mode="+$j.mode)
   Write-Output ("allow_autonomous_send="+$j.allowAutonomousSend)
   Write-Output ("auto_continue="+$j.autoContinueEnabled)
   Write-Output ("max_parallel="+$j.maxParallelAgents)
  }else{
   Write-Output ("r42_hold_active="+$j.holdActive)
  }
 }catch{Write-Output ($file+'=INVALID_OR_UNREADABLE')}
}
Write-Output '=== END ==='
